#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_colCount;
uniform float amzp_rowCount;
uniform float amzp_gapSize;
uniform float amzp_progress;
uniform float amzp_zDepth;
uniform float amzp_speedVar;
uniform float amzp_delaySpread;
uniform float amzp_breakOrder;
uniform float amzp_fadeOut;
    float hash1(float n){ return fract(sin(n*127.1)*43758.5453); }
    float hash2(float2 p){ return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
    float4 sampleTex(float2 uv){
      return amzTexture(0, clamp(uv,0.0,1.0));
    }
    float tileDelay(float2 id, float2 grid){
      float2 norm = id / max(grid-1.0, 1.0);
      float2 c = norm - 0.5;
      if(int(amzp_breakOrder)==0) return hash2(id);
      if(int(amzp_breakOrder)==1) return length(c)*1.414;
      if(int(amzp_breakOrder)==2) return norm.x;
      if(int(amzp_breakOrder)==3) return norm.y;
      return length(norm)*1.414;
    }
    void amzRender(){
      float2 uv = amzScreenNorm();
      float aspect = screen.zw.x / screen.zw.y;
      float2 grid = float2(amzp_colCount, amzp_rowCount);
      float cols = amzp_colCount;
      float rows = amzp_rowCount;
      float cellW = 1.0 / cols;
      float cellH = 1.0 / rows;
      float4 bg = float4(0.0);
      float4 bestColor = bg;
      float bestZ = -1.0;
      float searchR = ceil(max(cols,rows) * 0.5);
      float2 approxCell = uv * grid;
      float ix0 = max(floor(approxCell.x) - 3.0, 0.0);
      float ix1 = min(floor(approxCell.x) + 3.0, cols-1.0);
      float iy0 = max(floor(approxCell.y) - 3.0, 0.0);
      float iy1 = min(floor(approxCell.y) + 3.0, rows-1.0);
      for(float cy = 0.0; cy < 30.0; cy++){
        if(cy > amzp_rowCount-1.0) break;
        float iy = cy;
        for(float cx = 0.0; cx < 30.0; cx++){
          if(cx > amzp_colCount-1.0) break;
          float ix = cx;
          float2 cellID = float2(ix, iy);
          float2 origCenter = (cellID + 0.5) / grid;
          float rnd = hash2(cellID);
          float rndSpd = 1.0 + (rnd - 0.5)*2.0*amzp_speedVar;
          float del = tileDelay(cellID, grid) * amzp_delaySpread;
          float tileT = clamp(
            (amzp_progress - del) / max(1.0 - del, 0.001),
            0.0, 1.0
          );
          float eased = tileT * tileT * (3.0 - 2.0*tileT);
          float zPos = eased * amzp_zDepth * rndSpd;
          float focalLen = 2.0;
          float scale = focalLen / max(focalLen - zPos * 0.5, 0.001);
          float2 parallaxDir = origCenter - 0.5;
          float2 projCenter = 0.5 + parallaxDir * scale;
          float halfW = cellW * 0.5 * scale;
          float halfH = cellH * 0.5 * scale;
          float gap = amzp_gapSize * 0.5;
          float2 diff = uv - projCenter;
          float inW = halfW - gap;
          float inH = halfH - gap;
          if(abs(diff.x) <= inW && abs(diff.y) <= inH){
            if(zPos > bestZ){
              bestZ = zPos;
              float2 localUV = (uv - projCenter) / scale + origCenter;
              float4 tileCol = sampleTex(localUV);
              float fade = 1.0 - eased * amzp_fadeOut;
              tileCol.a *= clamp(fade, 0.0, 1.0);
              tileCol.rgb = clamp(tileCol.rgb, 0.0, 1.0);
              bestColor = tileCol;
            }
          }
        }
      }
      if(bestZ < 0.0){
        if(false){
          float2 gridUV = fract(uv * float2(amzp_colCount, amzp_rowCount));
          float gridLine = 1.0 - step(amzp_gapSize + 0.01, min(
            min(gridUV.x, 1.0 - gridUV.x),
            min(gridUV.y, 1.0 - gridUV.y)
          ));
          amzOutput = float4(1.0, 1.0, 1.0, gridLine * 0.5);
        } else {
          amzOutput = float4(0.0);
        }
      } else {
        float a = bestColor.a;
        if(false){
          float2 cellID2 = floor(uv * float2(amzp_colCount, amzp_rowCount));
          float2 cellFr = fract(uv * float2(amzp_colCount, amzp_rowCount));
          float edge = 1.0 - smoothstep(0.0, 0.06,
            min(min(cellFr.x, 1.0-cellFr.x),
                min(cellFr.y, 1.0-cellFr.y)));
          float3 guideCol = mix(bestColor.rgb, float3(0.0, 0.8, 1.0), edge * 0.6);
          amzOutput = float4(guideCol * a, a);
        } else {
          amzOutput = float4(bestColor.rgb * a, a);
        }
      }
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

